+/**
+ * Call fn(line) for each newline-separated line of str, without the newline.
+ * An empty str produces one empty line; a trailing newline does not produce
+ * an extra one. Intended for logging multi-line text one log message per line,
+ * since a log message cannot contain a newline (see LogEscapeMessage).
+ */
+template <typename Fn>
+void SplitLines(std::string_view str, Fn&& fn)
+{
+    do {
+        const size_t pos{str.find('\n')};
+        fn(str.substr(0, pos));
+        if (pos == std::string_view::npos) break;
+        str.remove_prefix(pos + 1);
+    } while (!str.empty());
+}
+
